insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('saitama-stadium-2002', '埼玉スタジアム2002', '埼玉県', '埼玉県さいたま市緑区美園二丁目1番地', 35.90311, 139.7176, '[{"name":"浦和美園","kind":"shuttle","walk_min":null,"note":"3番のりばから試合日の行きだけシャトルバス（約10分、大人240円）。徒歩なら歩行者専用道を約20分（クラブ公式。県の案内は15分）","toyoko":[{"hotel":"00283","name":"東横INN浦和美園駅東口","walk_min":2}]},{"name":"北越谷","kind":"shuttle","walk_min":null,"note":"1番のりばからシャトルバス（約25分、大人400円）。J1・カップ戦の土日祝の試合のみ、往復の運行","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://www.urawa-reds.co.jp/ticket/guide/saisuta2002/', '浦和美園駅（行きのみ・約10分・240円）と北越谷駅（往復・約25分・400円）から有料のシャトルバス。県の案内では大規模な試合の日に浦和駅・東浦和駅からも出る', '試合の日はスタジアム敷地内に一般の駐車場がなく、公共交通をすすめている。周辺の民間駐車場はクラブは案内しない。試合によっては数量限定の駐車券を売ることがある', '{"type":"city","id":18827,"name":"さいたま"}'::jsonb, '2026-11-12') on conflict do nothing;
