insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('sanga-stadium-kyocera', 'サンガスタジアム by KYOCERA', '京都府', '京都府亀岡市亀岡駅北1丁目8番地2', 35.01694, 135.58472, '[{"name":"亀岡","kind":"nearest","walk_min":3,"note":"JR嵯峨野線の駅から徒歩。京都駅・桂川・桂方面から直行バスが出る試合もあり、亀岡駅北口バス停で降りてすぐ","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://www.sanga-fc.jp/guide/homestadium', '京阪京都交通の直行シャトルバスが桂川・桂駅東口経由で亀岡駅北口に着く。運行は試合ごとに変わるので、試合ページで確かめる', 'スタジアムに駐車場はなく、公共交通での来場をすすめている', '{"type":"region","id":1418,"name":"亀岡"}'::jsonb, '2026-11-12') on conflict do nothing;
