insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('mito-shinkin-stadium', '水戸信用金庫スタジアム', '茨城県', '茨城県那珂市向山1282-1', 36.45721, 140.53819, '[{"name":"東海","kind":"shuttle","walk_min":null,"note":"西口（東口ではない）から無料シャトルバスで約10分。試合開始の6時間前から運行","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://www.mito-hollyhock.net/match/stadium/mito', '東海駅西口・東海村役場・那珂市役所前から無料シャトルバス（約10〜20分）。帰りは笠松運動公園の第4駐車場から、満員になり次第出発', '駐車場は試合ごとに使える場所が変わり、予約制（akippa）が中心。公園付属の先着の駐車場もある。有料・無料が混在', '{"type":"city","id":107030,"name":"水戸"}'::jsonb, '2026-11-12') on conflict do nothing;
