insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('denka-big-swan', 'デンカビッグスワンスタジアム', '新潟県', '新潟県新潟市中央区清五郎67-12', 37.88261, 139.05917, '[{"name":"新潟","kind":"shuttle","walk_min":null,"note":"南口の臨時バスのりば（プラーカ2前）から直行バス約20分（片道300円）。路線バスなら16番線のりばの「スポーツ公園線」で「ビッグスワン前」などへ約20分","toyoko":[{"hotel":"00060","name":"東横INN新潟駅前","walk_min":1}]}]'::jsonb, '[{"iata":"KIJ","name":"新潟空港","station":"新潟","access_min":60,"note":"リムジンバスで新潟駅まで約25分、そこからシャトルバス約20分。乗り継ぎを含めた合計の目安"}]'::jsonb, 'https://www.albirex.co.jp/guide/access/', 'ホームゲーム時のみ。往路は試合開始3時間30分前から、復路は試合終了後に約45分間随時（状況により変わる）。片道300円、小人150円。ICカード可。クラブは原則このバスをすすめている', '事前購入の駐車券が必要（前売り1,300〜1,700円、当日は500円高い。現地精算不可）。利用は試合開始5時間前〜終了後1時間30分後、再入場不可', '{"type":"city","id":9732,"name":"新潟"}'::jsonb, '2026-11-12') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('nippatsu-mitsuzawa', 'ニッパツ三ツ沢球技場', '神奈川県', '神奈川県横浜市神奈川区三ツ沢西町3-1', 35.46916, 139.60374, '[{"name":"横浜","kind":"shuttle","walk_min":null,"note":"西口バスターミナルの6〜11番のりばから路線バスで約10分、「三ツ沢総合グランド入口」か「市民病院」下車、徒歩約2分。試合日は西口第3ターミナル32番のりばから臨時直行バス（台数に限りあり）","toyoko":[{"hotel":"00357","name":"東横INN横浜駅西口","walk_min":7}]},{"name":"三ツ沢上町","kind":"nearest","walk_min":15,"note":"市営地下鉄ブルーライン。横浜から2駅（約4分）、駅から徒歩約15分","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://www.yokohamafc.com/guide/access-map/', '横浜駅西口第3ターミナル32番のりばから臨時直行バス（キックオフ約2時間前〜約40分前）。帰りの直行便は運行が確約されていないので、市民病院バス停で確かめる', '専用駐車場の案内はなく、試合日は公共交通機関の利用が求められている。近隣施設への駐車は控えるよう呼びかけがある', '{"type":"city","id":4590,"name":"横浜"}'::jsonb, '2026-11-12') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('toyama-sogo-stadium', '富山県総合運動公園陸上競技場', '富山県', '富山県富山市南中田368', 36.62506, 137.19569, '[{"name":"富山","kind":"shuttle","walk_min":null,"note":"ホームゲームの日だけ富山駅から臨時の直行バスが出る。通常の路線バスは2系統あり、栗山・栗山南口方面の系統は本数が多め、総合運動公園行きは本数が少ない。時刻は試合ごとに確かめる","toyoko":[{"hotel":"00004","name":"東横INN富山駅新幹線口2","walk_min":2},{"hotel":"00201","name":"東横INN富山駅新幹線口1","walk_min":5}]}]'::jsonb, '[{"iata":"TOY","name":"富山きときと空港","station":null,"access_min":8,"note":"空港からスタジアムまでタクシーで約8分、徒歩だと約35分（クラブ公式の案内）。路線バスもあるが本数は少ない"}]'::jsonb, 'https://www.kataller.co.jp/game/stadium/', 'ホームゲームの日に富山駅から臨時直行バスが運行される。運行の有無・時刻・料金は試合ごとの告知で確かめる', '駐車場は台数が限られ周辺は大変混雑する。通常は無料だが、混雑が見込まれる試合は有料になることがある。路上駐車は禁止。公共交通での来場をすすめている', '{"type":"city","id":3492,"name":"富山"}'::jsonb, '2026-11-12') on conflict do nothing;
