insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('fujieda-soccer-stadium', '藤枝総合運動公園サッカー場', '静岡県', '静岡県藤枝市原100', 34.88147, 138.23276, '[{"name":"藤枝","kind":"shuttle","walk_min":null,"note":"北口から有料シャトルバスで20〜30分（混雑で変わる）。タクシーは約15分","toyoko":[{"hotel":"00188","name":"東横INN静岡藤枝駅北口","walk_min":1}]}]'::jsonb, '[]'::jsonb, 'https://myfc.co.jp/stadium/', '藤枝駅北口から有料シャトルバス（大人500円・小学生以下250円、2026年から完全キャッシュレス）。随時運行、天皇杯は対象外。帰りはスタジアム側の乗り場から。時刻は試合ごとの告知で確かめる', '周辺の駐車場はすべて有料の予約制（公式チケットサイトまたは駐車場予約サイト）。第1駐車場1,500円、第5駐車場1,200円など。路上の乗降・駐停車は不可', '{"type":"region","id":732,"name":"焼津・藤枝"}'::jsonb, '2026-11-12') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('plife-foods-stadium', 'プライフーズスタジアム', '青森県', '青森県八戸市大字市川町字市川後55-1', 40.59047, 141.45611, '[{"name":"八戸","kind":"shuttle","walk_min":null,"note":"ホーム開催日は事前予約の「応援タクシー定額運行」で約30分、片道3,740円。電車の最寄り駅はなく、八戸駅からタクシーで約25分","toyoko":[{"hotel":"00106","name":"東横INN八戸駅前","walk_min":1}]},{"name":"陸奥市川","kind":"nearest","walk_min":null,"note":"駅前から市営バスで約20分、「市川」バス停下車、徒歩約5分","toyoko":[]},{"name":"本八戸","kind":"nearest","walk_min":null,"note":"駅前バス停から市営バス「多賀台団地行き」で約30分、「市川」下車、徒歩約5分","toyoko":[]}]'::jsonb, '[{"iata":"MSJ","name":"三沢空港","station":null,"access_min":40,"note":"ホーム開催日の応援タクシー定額運行（事前予約、片道4,990円）で約40分"}]'::jsonb, 'https://vanraure.net/stadium', 'シャトルバスではなく、ホーム開催日に事前予約制の応援タクシー定額運行（八戸駅・中心街・三沢空港から直通、1台4名まで）。予約は三八五交通', '合計約1,494台（常設約396台、多目的広場の臨時約1,000台など）。有料か・予約制かは未確認', '{"type":"city","id":21378,"name":"八戸"}'::jsonb, '2026-11-12') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('city-football-station', 'CITY FOOTBALL STATION', '栃木県', '栃木県栃木市岩舟町三谷1038-1', 36.3375, 139.64528, '[{"name":"岩舟","kind":"nearest","walk_min":30,"note":"JR両毛線の岩舟駅から徒歩30〜40分、タクシーなら約5分（駅前にタクシー会社）。ふれあいバス（岩舟駅・栃木駅から）が隣の遊楽々館に停まるが、夜の試合の後は運行がない","toyoko":[]}]'::jsonb, '[]'::jsonb, 'https://tochigi-city.com/watching/stadium/', '臨時駐車場とスタジアムの間をシャトルバスが走る。時刻は試合ごとの試合情報で確かめる。駅からのシャトルは公式にない', '公園内の駐車場は無料だが台数が限られ、試合日は7:30から。近くの駐車場は akippa で予約できる', '{"type":"city","id":108449,"name":"佐野"}'::jsonb, '2026-11-12') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('asics-satoyama-stadium', 'アシックス里山スタジアム', '愛媛県', '愛媛県今治市高橋ふれあいの丘1-3', 34.04056, 132.95867, '[{"name":"今治","kind":"shuttle","walk_min":null,"note":"試合日は今治駅前からイオンモール今治新都市への無料シャトル（約20分、先着順）。路線バスはせとうちバスで約15分、「イオンモール今治新都市」から徒歩約10分。徒歩は約5kmで非推奨","toyoko":[]}]'::jsonb, '[{"iata":"MYJ","name":"松山空港","station":"今治","access_min":110,"note":"空港リムジンバスで今治駅まで約90分、そこからシャトル約20分（合計は目安）"}]'::jsonb, 'https://www.fcimabari.com/access', '今治駅前〜イオンモール今治新都市の無料シャトル（2026/27シーズン）。往路はチケット提示が必要で、復路は満席で終了。このほか駐車場Bとスタジアムを結ぶ無料の循環シャトルもある。運行は試合ごとに変わるので告知で確かめる。路線バスの終バスに注意（夜は20時台）', '一般駐車場（約1,300台）などがあり、3人以上の乗り合いをすすめている。指定外への駐車は控える案内', '{"type":"city","id":106392,"name":"今治"}'::jsonb, '2026-11-12') on conflict do nothing;
insert into public.stadiums (id, name, prefecture, address, lat, lng, stations, airports, access_url, shuttle_note, parking_note, agoda_area, verified_at) values ('jit-recycle-ink-stadium', 'JITリサイクルインクスタジアム', '山梨県', '山梨県甲府市小瀬町840', 35.62228, 138.5897, '[{"name":"甲府","kind":"shuttle","walk_min":null,"note":"南口の2番のりばから山梨交通の直行バスで約30分。南口3番のりばの路線バス（小瀬スポーツ公園行き）も約30分。タクシーは約20分","toyoko":[{"hotel":"00132","name":"東横INN甲府駅南口2","walk_min":1},{"hotel":"00072","name":"東横INN甲府駅南口1","walk_min":10}]}]'::jsonb, '[]'::jsonb, 'https://www.ventforet.jp/guide/stadium_access.html', '甲府駅南口から山梨交通の直行バス（約15分間隔、試合の3時間30分前から運行、終了後も約1時間運行）。片道は大人440円・往復700円。時刻は試合ごとの告知で確かめる', '小瀬スポーツ公園内に第1〜第5駐車場（普通車で合計約2,088台）がある。近隣は混雑するため公共交通をすすめている。臨時駐車場（約800台）は不定期で、試合の3日前のお知らせで確かめる', '{"type":"city","id":108843,"name":"甲府"}'::jsonb, '2026-11-12') on conflict do nothing;
